struct Handle {
    Handle(Handle&&) = default;
};

struct Owner {
    Handle handle;
    int&& pending;
    int count;
};

struct Lock {
    Lock(const Lock&) = delete;
};

struct Pinned {
    Lock lock;
    int count;
};

template <class T>
struct Slot {
    Slot(Slot&&) = default;
    Slot(const Slot&) = delete;
};

template <class T>
struct Holder {
    Slot<T> slot;
    int count;
};

#pragma once

namespace std {
template <class T>
T&& move(T& value);
}

